WITH стр AS (SELECT c0.value AS вопрос, string_agg(c.value, ' ' ORDER BY c.col) AS текст FROM project_document_cells c0 JOIN project_document_cells c ON c.project_id = c0.project_id AND c.entity_kind = c0.entity_kind AND c.entity_name = c0.entity_name AND c.block_ord = c0.block_ord AND c.row_ord = c0.row_ord JOIN scheme($1) r ON r.role = 'register.questions' AND c0.entity_name = r.value WHERE c0.project_id = $1 AND c0.entity_kind = 'index' AND c0.col = 0 AND c0.value ~ '^Q-[0-9]+' GROUP BY c0.value) SELECT s.вопрос || ' — строка говорит о решении владельца, а исполнения не называет' AS detail FROM стр s WHERE EXISTS (SELECT 1 FROM scheme($1) d WHERE d.role = 'word.decided-by-owner' AND s.текст ~* d.value) AND NOT EXISTS (SELECT 1 FROM scheme($1) e WHERE e.role = 'word.executed' AND s.текст ~* ('(^|[^а-яё])' || e.value)) ORDER BY 1
